def recalculate_automatic_prices(apps, schema_editor):
    Product = apps.get_model('products', 'Product')
    CompanySettings = apps.get_model('products', 'CompanySettings')
    settings_by_company = {
        settings.company_id: settings
        for settings in CompanySettings.objects.select_related('company').all()
    }
    products = Product.objects.filter(sale_price_mode='automatic').select_related('category', 'company')
    for product in products.iterator():
        settings = settings_by_company.get(product.company_id)
        if settings is None or not product.weight_kg or product.weight_kg <= 0:
            product.sale_price = ZERO
            product.save(update_fields=['sale_price'])
            continue
        purchase_cost = (product.purchase_price or ZERO) * settings.cny_to_local_rate
        international_logistics = (
            product.weight_kg
            * settings.logistics_cost_per_kg_usd
            * settings.usd_to_local_rate
        )
        landed_cost = purchase_cost + international_logistics
        before_packaging = landed_cost * (Decimal('1.00') + settings.internal_logistics_pct)
        cost_price = (before_packaging * (Decimal('1.00') + settings.packaging_pct)).quantize(CENT)
        markup = (
            product.category.margin_pct
            if product.category_id and product.category.margin_pct is not None
            else settings.margin_pct
        )
        deduction_rate = settings.retail_tax_pct + settings.acquiring_pct
        if deduction_rate >= Decimal('1.00'):
            continue
        price = cost_price * (Decimal('1.00') + markup) / (Decimal('1.00') - deduction_rate)
        currency_code = (product.company.base_currency_code or '').upper()
        quantum = Decimal('1') if currency_code in {'KZT', 'RUB'} else CENT
        product.sale_price = price.quantize(quantum, rounding=ROUND_HALF_UP)
        product.save(update_fields=['sale_price'])


